<?php get_header();
$categories=get_categories(array('hide_empty'=>true));
$posts=new WP_Query(array('post_type'=>'post','posts_per_page'=>20,'post_status'=>'publish'));
?><main id="main" class="canvas"><section class="vault" id="projects"><label class="search-shell" id="search-shell"><span class="search-prompt">grep -i</span><i class="fake-cursor" aria-hidden="true"></i><input id="journal-search" type="search" placeholder="" autocomplete="off"><kbd class="key-hint">⌘K</kbd></label><div class="filterbar"><button class="filter active" data-filter="all">All</button><?php foreach($categories as $c):?><button class="filter" data-filter="<?php echo esc_attr($c->slug); ?>"><?php echo esc_html($c->name); ?></button><?php endforeach;?></div><div class="posts"><?php if($posts->have_posts()):$i=1;while($posts->have_posts()):$posts->the_post();$cat=get_the_category();$slug=$cat?sanitize_html_class($cat[0]->slug):'uncategorized';$name=$cat?$cat[0]->name:'Uncategorized';$search_text=wp_strip_all_tags(get_the_title().' '.$name.' '.get_the_excerpt());?><a class="post-row" data-category="<?php echo esc_attr($slug); ?>" data-search="<?php echo esc_attr($search_text); ?>" href="<?php the_permalink(); ?>"><span class="code">LOG-<?php echo str_pad($i,3,'0',STR_PAD_LEFT); ?></span><span class="pill <?php echo $i===1?'active-pill':''; ?>"><?php echo $i===1?'LATEST':esc_html(strtoupper($name)); ?></span><span class="post-title"><?php the_title(); ?></span><span class="meta"><?php echo esc_html($name); ?></span><time class="date"><?php echo esc_html(get_the_date('Y.m.d')); ?></time><i class="arrow">→</i></a><?php $i++;endwhile;wp_reset_postdata();else:?><div class="empty">◉ ◉ ◉ 暂无文章。请到后台 → 文章 → 写文章发布；发布后会自动显示在这里。</div><?php endif;?></div><div class="no-results" id="no-results">0 results / no matching entries found</div></section><section class="activity" id="archive"><div class="titlebar"><h2>Workspace Activity</h2><p>LOG / CATEGORIES / RECENT UPDATES</p></div><div class="activity-grid"><article class="panel"><div class="panel-head"><h2>Recent posts</h2></div><div class="log"><?php $recent=get_posts(array('numberposts'=>3,'post_status'=>'publish'));if($recent):foreach($recent as $post):setup_postdata($post);?><div><time><?php echo esc_html(get_the_date('Y.m.d')); ?></time><a href="<?php the_permalink(); ?>"><?php the_title(); ?></a></div><?php endforeach;wp_reset_postdata();else:?><div><time>READY</time><span>—</span></div><?php endif;?></div></article><article class="panel"><div class="panel-head"><h2>Categories</h2></div><div class="chips"><?php if($categories):foreach($categories as $c):?><a class="chip" href="<?php echo esc_url(get_category_link($c->term_id)); ?>"><?php echo esc_html($c->name); ?> · <?php echo esc_html($c->count); ?></a><?php endforeach;else:?><span class="chip">Create categories in Posts</span><?php endif;?></div></article></div></section></main><?php get_footer(); ?>